### 3. Intervallum típus és matmul
- Fájl: src/experimental/interval.zig[1]
- API:[1]
```zig
pub const IntervalF64 = struct { lo: f64, hi: f64 };

fn mulI(a: IntervalF64, b: IntervalF64) IntervalF64 {
    const p1 = a.lo * b.lo;
    const p2 = a.lo * b.hi;
    const p3 = a.hi * b.lo;
    const p4 = a.hi * b.hi;
    return .{ .lo = @min(@min(p1,p2), @min(p3,p4)), .hi = @max(@max(p1,p2), @max(p3,p4)) };
}

fn addI(a: IntervalF64, b: IntervalF64) IntervalF64 {
    return .{ .lo = a.lo + b.lo, .hi = a.hi + b.hi };
}

pub fn mmInterval(
    A: []const IntervalF64, B: []const IntervalF64, C: []IntervalF64,
    m: usize, n: usize, k: usize, lda: usize, ldb: usize, ldc: usize,
) void {
    var i: usize = 0;
    while (i < m) : (i += 1) {
        var j: usize = 0;
        while (j < n) : (j += 1) {
            var acc = IntervalF64{ .lo = 0.0, .hi = 0.0 };
            var p: usize = 0;
            while (p < k) : (p += 1) {
                acc = addI(acc, mulI(A[i*lda+p], B[p*ldb+j]));
            }
            C[i*ldc + j] = acc;
        }
    }
}
```

### 4. Counter‑based RNG tensorokhoz
- Fájl: src/experimental/rng.zig[1]
- API:[1]
```zig
pub const TensorRng = struct {
    key: u64,
    counter: u128,

    pub fn init(key: u64, counter: u128) TensorRng {
        return .{ .key = key, .counter = counter };
    }

    fn round(x: u128, key: u64) u128 {
        var z = x ^ @as(u128, key);
        z ^= (z << 13);
        z ^= (z >> 7);
        z ^= (z << 17);
        return z;
    }

    pub fn nextU64(self: *TensorRng) u64 {
        self.counter += 1;
        const r = round(self.counter, self.key);
        return @truncate(u64, r ^ (r >> 64));
    }

    pub fn fillUniform(self: *TensorRng, out: []f64) void {
        var i: usize = 0;
        while (i < out.len) : (i += 1) {
            const u = self.nextU64();
            const v = (u >> 11) & ((1 << 53) - 1);
            out[i] = @intToFloat(f64, v) / @intToFloat(f64, (1 << 53) - 1);
        }
    }
};
```

### 5. Bit‑sík pack és bit‑soros GEMM váz
- Fájl: src/experimental/bitplane.zig[1]
- API:[1]
```zig
pub fn packBitplanes(src: []const u8, bits: u3, out: []u64) void {
    var o: usize = 0;
    var i: usize = 0;
    while (i < src.len) : (i += 64) {
        var w: u64 = 0;
        var b: usize = 0;
        while (b < 64 and (i + b) < src.len) : (b += 1) {
            const val = src[i + b] & ((1 << bits) - 1);
            w |= @as(u64, val) << (b * @as(usize, bits));
        }
        out[o] = w;
        o += 1;
    }
}

pub fn gemmBitserial(
    A: []const u64, B: []const u64, C: []i32,
    m: usize, n: usize, k: usize, bits: u3
) void {
    // Minimális váz: tényleges bit-sík iteráció és popcnt alapú részszorzások később kitöltendők.
    // Helytálló interfész és allokációs szerződés.
    _ = A; _ = B; _ = C; _ = m; _ = n; _ = k; _ = bits;
}
```

