### 7. NTT + CRT
- Fájl: src/experimental/ntt.zig[1]
- API:[1]
```zig
pub fn modPow(mut_base: u64, mut_exp: u64, modp: u64) u64 {
    var res: u64 = 1;
    var b = mut_base % modp;
    var e = mut_exp;
    while (e > 0) : (e >>= 1) {
        if ((e & 1) == 1) res = @intCast(u64, (res *% b) % modp);
        b = @intCast(u64, (b *% b) % modp);
    }
    return res;
}

pub fn ntt_inplace(a: []u64, modp: u64, root: u64) void {
    // Iteratív Cooley–Tukey váz, később teljesítményhangolással.
    _ = a; _ = modp; _ = root;
}

pub fn crtMerge(residues: []const u64, moduli: []const u64) u128 {
    // Kínai maradéktétel váz; interfész stabil.
    _ = residues; _ = moduli;
    return 0;
}
```

### 8. ShadowTensor – ULP hiba követés
- Fájl: src/experimental/shadow.zig[1]
- API:[1]
```zig
pub const ShadowTensor = struct {
    ulp: []f32,
    pub fn init(buf: []f32) ShadowTensor { return .{ .ulp = buf }; }
};

pub fn addWithShadow(out: []f64, a: []const f64, b: []const f64, sh: *ShadowTensor) void {
    var i: usize = 0;
    while (i < out.len) : (i += 1) {
        const r = a[i] + b[i];
        out[i] = r;
        // Egyszerű ULP-becslés váz: differencia skálázása.
        const d = @fabs(a[i]) + @fabs(b[i]);
        sh.ulp[i] = @floatCast(f32, @fabs(r) / (@max(d, 1e-30)));
    }
}
```

### 9. Cache‑oblivious GEMM váz
- Fájl: src/experimental/cacheobliv.zig[1]
- API:[1]
```zig
pub fn gemmCacheOblivious(
    A: []const f64, B: []const f64, C: []f64,
    m: usize, n: usize, k: usize,
    lda: usize, ldb: usize, ldc: usize
) void {
    // Rekurzív vágás váz (stop condition + 3-way bontás).
    if (m*n*k <= 4096) {
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var acc = 0.0;
                var p: usize = 0;
                while (p < k) : (p += 1) {
                    acc += A[i*lda + p] * B[p*ldb + j];
                }
                C[i*ldc + j] += acc;
            }
        }
        return;
    }
    // További rekurzív bontás később kitölthető.
}
```

### 10. Merkle‑fás snapshot
- Fájl: src/experimental/merkle.zig[1]
- API:[1]
```zig
const std = @import("std");

pub fn merkleHashBlocks(comptime T: type, data: []const T, block_elems: usize, out: []u64) void {
    var i: usize = 0;
    var o: usize = 0;
    while (i < data.len) : (i += block_elems) {
        var h: u64 = 1469598103934665603; // FNV-1a offset
        var j: usize = 0;
        while (j < block_elems and (i + j) < data.len) : (j += 1) {
            const b = @bitCast(u64, data[i + j]);
            h = (h ^ b) * 1099511628211;
        }
        out[o] = h;
        o += 1;
    }
}
```

### 11. Taint tracking
- Fájl: src/experimental/taint.zig[1]
- API:[1]
```zig
pub const Taint = struct {
    bits: []u8, // 1 bit/elem vagy 1 byte/elem
};

pub fn mmWithTaint(
    out: []f64, tout: []u8,
    A: []const f64, ta: []const u8,
    B: []const f64, tb: []const u8,
    m: usize, n: usize, k: usize, lda: usize, ldb: usize, ldc: usize
) void {
    var i: usize = 0;
    while (i < m) : (i += 1) {
        var j: usize = 0;
        while (j < n) : (j += 1) {
            var t: u8 = 0;
            var p: usize = 0;
            var acc = 0.0;
            while (p < k) : (p += 1) {
                const a = A[i*lda+p];
                const b = B[p*ldb+j];
                acc += a * b;
                t |= ta[i*lda+p] | tb[p*ldb+j];
            }
            out[i*ldc + j] = acc;
            tout[i*ldc + j] = t;
        }
    }
}
```

### 12. Konstans‑idő argmax
- Fájl: src/experimental/secure.zig[1]
- API:[1]
```zig
pub fn argmaxCt(x: []const f64) usize {
    var max_val = -std.math.inf(f64);
    var idx: usize = 0;
    var i: usize = 0;
    while (i < x.len) : (i += 1) {
        const gt = @intFromBool(x[i] > max_val);
        // branchless választás
        max_val = @bitCast(f64, (@bitCast(u64, max_val) & ~(@as(u64, 0) -% gt))) |
                           (@bitCast(u64, x[i]) & (@as(u64, 0) -% gt));
        // index frissítés maszkosan
        idx = (idx & ~gt) | (i & gt);
    }
    return idx;
}
```

