### 15. Tesztek
- Hozz létre tests/experimental.zig fájlt, minimális sanity‑tesztekkel:[1]
```zig
const std = @import("std");
const layout = @import("../src/experimental/layout.zig");
const semiring = @import("../src/experimental/semiring.zig");
const interval = @import("../src/experimental/interval.zig");
const rng = @import("../src/experimental/rng.zig");
const taint = @import("../src/experimental/taint.zig");

test "morton basic" {
    try std.testing.expect(layout.mortonIndex2D(1,1) == 3);
}

test "semiring min-plus small" {
    var A = [_]f64{0,1,2,  1,0,3};
    var B = [_]f64{0,2,1,  4,0,5};
    var C = [_]f64{0} ** 6;
    semiring.gemmMinPlus(&A, &B, &C, 2, 3, 2, 2, 3, 3);
    // nincs pontos elvárás, csak hogy ne fusson hibára
    try std.testing.expect(C.len == 6);
}

test "interval mm shape" {
    var A = [_]interval.IntervalF64{ .{.lo=1,.hi=2}, .{.lo=0,.hi=1} };
    var B = [_]interval.IntervalF64{ .{.lo=2,.hi=3}, .{.lo=-1,.hi=0} };
    var C = [_]interval.IntervalF64{.{.lo=0,.hi=0}} ** 1;
    interval.mmInterval(&A, &B, &C, 1, 1, 2, 2, 1, 1);
    try std.testing.expect(C[0].hi >= C[0].lo);
}

test "rng fill" {
    var buf: [8]f64 = undefined;
    var r = rng.TensorRng.init(0xdeadbeef, 0);
    r.fillUniform(buf[0..]);
    try std.testing.expect(buf[0] >= 0 and buf[0] <= 1);
}

test "taint mm shape" {
    var A = [_]f64{1,2,3,4};
    var B = [_]f64{5,6,7,8,9,10};
    var ta = [_]u8{1,0,0,1};
    var tb = [_]u8{0,1,0,1,0,1};
    var C = [_]f64{0,0,0,0,0,0};
    var tc = [_]u8{0,0,0,0,0,0};
    taint.mmWithTaint(&C, &tc, &A, &ta, &B, &tb, 2, 3, 2, 2, 3, 3);
    try std.testing.expect(tc[0] | tc[1] | tc[2] | tc[3] | tc[4] | tc[5] >= 0);
}
```
