    +pub fn xavier_init(t: *Tensor, seed: u64) void {
    +    var prng = std.rand.DefaultPrng.init(seed);
    +    const r = prng.random();
    +    const fan_in = if (t.shape.len >= 1) t.shape[t.shape.len - 1] else 1;
    +    const fan_out = if (t.shape.len >= 1) t.shape else 1;
    +    const limit = @sqrt(6.0 / (@as(f64, @floatFromInt(fan_in + fan_out))));
    +    const total = totalElements(t.shape);
    +    var i: usize = 0;
    +    while (i < total) : (i += 1) {
    +        t.data[t.offset + i] = (r.float(f64) * 2.0 - 1.0) * limit;
    +    }
