    +pub fn avgpool2d(self: *const Tensor, kernel_size: usize, stride: usize, allocator: Allocator) !Tensor {
    +    if (self.shape.len != 4) return error.InvalidShapeForPool;
    +    const batch = self.shape;
    +    const channels = self.shape;[3]
    +    const in_h = self.shape;[1]
    +    const in_w = self.shape;[2]
    +    const out_h = (in_h - kernel_size) / stride + 1;
    +    const out_w = (in_w - kernel_size) / stride + 1;
    +    var out = try Tensor.init(allocator, &.{ batch, channels, out_h, out_w }, .f64);
    +    var b: usize = 0;
    +    while (b < batch) : (b += 1) {
    +        var c: usize = 0;
    +        while (c < channels) : (c += 1) {
    +            var oh: usize = 0;
    +            while (oh < out_h) : (oh += 1) {
    +                var ow: usize = 0;
    +                while (ow < out_w) : (ow += 1) {
    +                    var sum: f64 = 0;
    +                    var cnt: usize = 0;
    +                    var kh: usize = 0;
    +                    while (kh < kernel_size) : (kh += 1) {
    +                        const ih = stride * oh + kh;
    +                        if (ih >= in_h) break;
    +                        var kw: usize = 0;
    +                        while (kw < kernel_size) : (kw += 1) {
    +                            const iw = stride * ow + kw;
    +                            if (iw >= in_w) break;
    +                            sum += self.get(&.{ b, c, ih, iw });
    +                            cnt += 1;
    +                        }
    +                    }
    +                    out.set(&.{ b, c, oh, ow }, sum / @as(f64, @floatFromInt(cnt)));
    +                }
    +            }
    +        }
    +    }
    +    return out;
    +}
